ALTER TABLE messages ADD COLUMN package_plan text;
ALTER TABLE messages ADD COLUMN tracking_expires_at timestamptz;
ALTER TABLE messages ADD COLUMN first_open_only boolean NOT NULL DEFAULT false;
CREATE INDEX messages_tracking_expiry ON messages(tracking_expires_at) WHERE tracking_expires_at IS NOT NULL;
CREATE TABLE package_usage(workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,kind text NOT NULL CHECK(kind IN ('bulk_month','bulk_day','link_month')),period date NOT NULL,used integer NOT NULL DEFAULT 0 CHECK(used>=0),PRIMARY KEY(workspace_id,kind,period));
CREATE TABLE tracked_links(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,message_id uuid NOT NULL,token_hash text UNIQUE NOT NULL,url_sealed text NOT NULL,expires_at timestamptz NOT NULL,FOREIGN KEY(workspace_id,message_id) REFERENCES messages(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE link_events(id uuid PRIMARY KEY,link_id uuid NOT NULL REFERENCES tracked_links(id) ON DELETE CASCADE,occurred_at timestamptz NOT NULL DEFAULT now(),source text NOT NULL);
CREATE INDEX link_events_list ON link_events(link_id,occurred_at);
CREATE TABLE member_notifications(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,message_id uuid REFERENCES messages(id) ON DELETE CASCADE,kind text NOT NULL CHECK(kind IN ('first_open','repeat_open','reminder')),dedupe text NOT NULL UNIQUE,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX member_notifications_list ON member_notifications(workspace_id,created_at DESC);
CREATE TABLE notification_preferences(workspace_id uuid PRIMARY KEY REFERENCES workspaces(id) ON DELETE CASCADE,opens boolean NOT NULL DEFAULT true,repeats boolean NOT NULL DEFAULT true,muted_until timestamptz,weekly_email boolean NOT NULL DEFAULT false);
CREATE TABLE mail_reminders(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,message_id uuid NOT NULL REFERENCES messages(id) ON DELETE CASCADE,due_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','done','cancelled')),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX mail_reminders_due ON mail_reminders(due_at) WHERE status='active';
CREATE TABLE scheduled_mail(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,request_id uuid NOT NULL,payload text NOT NULL,sender_email text NOT NULL,due_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','sending','sent','unknown','paused','cancelled')),message_id uuid REFERENCES messages(id) ON DELETE SET NULL,started_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,request_id));
CREATE INDEX scheduled_mail_due ON scheduled_mail(due_at) WHERE status='queued';
ALTER TABLE bulk_campaigns ADD COLUMN scheduled_at timestamptz;
ALTER TABLE bulk_campaigns ADD COLUMN quota_period date;
ALTER TABLE bulk_recipients ADD COLUMN daily_period date;
ALTER TABLE bulk_recipients ADD COLUMN suppression_hash text;
CREATE TABLE mail_suppressions(workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,email_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,email_hash));
CREATE TABLE unsubscribe_tokens(token_hash text PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,email_hash text NOT NULL,expires_at timestamptz NOT NULL);
ALTER TABLE scheduled_mail ADD COLUMN reason text;
CREATE TABLE summary_deliveries(workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,week_start date NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,week_start));
CREATE TABLE free_sender_usage(sender_hash text NOT NULL,usage_date date NOT NULL,used integer NOT NULL CHECK(used BETWEEN 0 AND 3),PRIMARY KEY(sender_hash,usage_date));
UPDATE bulk_campaigns SET quota_period=date_trunc('month',created_at AT TIME ZONE 'Europe/Istanbul')::date WHERE status<>'draft';
INSERT INTO package_usage(workspace_id,kind,period,used) SELECT c.workspace_id,'bulk_month',c.quota_period,count(*)::int FROM bulk_campaigns c JOIN bulk_recipients r ON r.campaign_id=c.id WHERE c.quota_period IS NOT NULL AND (r.reserved=true OR r.state IN ('sent','unknown')) GROUP BY c.workspace_id,c.quota_period ON CONFLICT DO NOTHING;
INSERT INTO package_usage(workspace_id,kind,period,used) SELECT workspace_id,'bulk_day',(created_at AT TIME ZONE 'Europe/Istanbul')::date,count(*)::int FROM messages WHERE send_channel='bulk' AND state IN ('sent','sending','unknown') GROUP BY workspace_id,(created_at AT TIME ZONE 'Europe/Istanbul')::date ON CONFLICT DO NOTHING;
CREATE TABLE expired_submissions(workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,idempotency_key text NOT NULL,payload_hash text NOT NULL,expired_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,idempotency_key));
